insert into public.faq(question,reponse,official,is_official,usage_count) select 'Qu''est-ce que Mr XPRONOS ?', '<p>Mr XPRONOS est un site d''informations et de pronostics de football. Tu peux consulter les rubriques <a href=''https://mrxpronos.github.io/MrXPRONOS_App/pronos.html''>Pronostics</a>, <a href=''https://mrxpronos.github.io/MrXPRONOS_App/live.html''>LIVE</a> et <a href=''https://mrxpronos.github.io/MrXPRONOS_App/historique.html''>Historique</a>.</p>', true, true, 0 where not exists (select 1 from public.faq where lower(question)=lower('Qu''est-ce que Mr XPRONOS ?'));
insert into public.faq(question,reponse,official,is_official,usage_count) select 'Où voir les pronostics du site ?', '<p>Consulte la page <a href=''https://mrxpronos.github.io/MrXPRONOS_App/pronos.html''>Pronostics</a> du site.</p>', true, true, 0 where not exists (select 1 from public.faq where lower(question)=lower('Où voir les pronostics du site ?'));
insert into public.faq(question,reponse,official,is_official,usage_count) select 'Où voir les anciens résultats ?', '<p>Retrouve les pronostics précédents sur la page <a href=''https://mrxpronos.github.io/MrXPRONOS_App/historique.html''>Historique</a>. Vérifie la date et le statut de chaque sélection.</p>', true, true, 0 where not exists (select 1 from public.faq where lower(question)=lower('Où voir les anciens résultats ?'));
insert into public.faq(question,reponse,official,is_official,usage_count) select 'Comment lire un pronostic ?', '<p>Regarde le match, le marché proposé, la sélection et la date. Un pronostic exprime une possibilité et ne garantit pas le résultat.</p>', true, true, 0 where not exists (select 1 from public.faq where lower(question)=lower('Comment lire un pronostic ?'));
insert into public.faq(question,reponse,official,is_official,usage_count) select 'Que signifie plus de 2,5 buts ?', '<p>Le marché « plus de 2,5 buts » correspond à au moins 3 buts au total dans le match.</p>', true, true, 0 where not exists (select 1 from public.faq where lower(question)=lower('Que signifie plus de 2,5 buts ?'));
insert into public.faq(question,reponse,official,is_official,usage_count) select 'Que signifie moins de 2,5 buts ?', '<p>Le marché « moins de 2,5 buts » correspond à 0, 1 ou 2 buts au total.</p>', true, true, 0 where not exists (select 1 from public.faq where lower(question)=lower('Que signifie moins de 2,5 buts ?'));
insert into public.faq(question,reponse,official,is_official,usage_count) select 'Que signifie BTTS ?', '<p>BTTS signifie « Both Teams To Score » : les deux équipes doivent marquer au moins un but chacune si la sélection est « Oui ».</p>', true, true, 0 where not exists (select 1 from public.faq where lower(question)=lower('Que signifie BTTS ?'));
insert into public.faq(question,reponse,official,is_official,usage_count) select 'Qu''est-ce qu''un corner ?', '<p>Un corner est un coup de pied de coin accordé lorsque le ballon franchit entièrement la ligne de but après avoir été touché en dernier par un défenseur, sans but marqué.</p>', true, true, 0 where not exists (select 1 from public.faq where lower(question)=lower('Qu''est-ce qu''un corner ?'));
insert into public.faq(question,reponse,official,is_official,usage_count) select 'Qu''est-ce qu''une cote ?', '<p>Une cote représente la rémunération potentielle d''un pari selon les règles de l''opérateur. Une cote plus élevée n''implique pas une meilleure probabilité de gagner.</p>', true, true, 0 where not exists (select 1 from public.faq where lower(question)=lower('Qu''est-ce qu''une cote ?'));
insert into public.faq(question,reponse,official,is_official,usage_count) select 'Qu''est-ce qu''un pari responsable ?', '<p>Parier comporte un risque de perte. Ne joue jamais de l''argent nécessaire à tes dépenses essentielles, fixe une limite et n''essaie pas de récupérer tes pertes en augmentant les mises. Le service est réservé aux adultes.</p>', true, true, 0 where not exists (select 1 from public.faq where lower(question)=lower('Qu''est-ce qu''un pari responsable ?'));
insert into public.faq(question,reponse,official,is_official,usage_count) select 'Un pronostic est-il garanti ?', '<p>Non. Aucun pronostic de football n''est garanti. Les statistiques et les analyses ne suppriment pas l''incertitude sportive.</p>', true, true, 0 where not exists (select 1 from public.faq where lower(question)=lower('Un pronostic est-il garanti ?'));
insert into public.faq(question,reponse,official,is_official,usage_count) select 'Comment vérifier une analyse de match ?', '<p>Vérifie la date, les équipes, la compétition, les statistiques disponibles et les absences connues. Les données LIVE peuvent changer rapidement et les analyses peuvent se tromper.</p>', true, true, 0 where not exists (select 1 from public.faq where lower(question)=lower('Comment vérifier une analyse de match ?'));
insert into public.faq(question,reponse,official,is_official,usage_count) select 'Quelle est la différence entre avant-match et live ?', '<p>Un pronostic avant-match est préparé avant le coup d''envoi. Un signal LIVE dépend des informations disponibles pendant la rencontre et peut vite devenir obsolète.</p>', true, true, 0 where not exists (select 1 from public.faq where lower(question)=lower('Quelle est la différence entre avant-match et live ?'));
insert into public.faq(question,reponse,official,is_official,usage_count) select 'Pourquoi un pronostic peut-il être perdu ?', '<p>Un match reste incertain : cartons, blessures, changements tactiques, erreurs et événements imprévus peuvent modifier son déroulement.</p>', true, true, 0 where not exists (select 1 from public.faq where lower(question)=lower('Pourquoi un pronostic peut-il être perdu ?'));
insert into public.faq(question,reponse,official,is_official,usage_count) select 'Comment utiliser la page LIVE ?', '<p>Ouvre la page <a href=''https://mrxpronos.github.io/MrXPRONOS_App/live.html''>LIVE</a> puis consulte les matchs et signaux disponibles. Vérifie toujours l''heure des données affichées.</p>', true, true, 0 where not exists (select 1 from public.faq where lower(question)=lower('Comment utiliser la page LIVE ?'));
insert into public.faq(question,reponse,official,is_official,usage_count) select 'Comment contacter Mr XPRONOS ?', '<p>Pour contacter l''équipe, consulte la page <a href=''https://mrxpronos.github.io/MrXPRONOS_App/contact.html''>Contact</a>.</p>', true, true, 0 where not exists (select 1 from public.faq where lower(question)=lower('Comment contacter Mr XPRONOS ?'));
